import math


def cosine_similarity(a: list[float], b: list[float]) -> float:
    dot = sum(p * q for p, q in zip(a, b))
    na = math.sqrt(sum(p * p for p in a))
    nb = math.sqrt(sum(q * q for q in b))
    if na == 0.0 or nb == 0.0:
        return 0.0
    return dot / (na * nb)

