def encode_run_length(s: str) -> str:
    if not s:
        return ""
    out = []
    current = s[0]
    count = 1
    for ch in s[1:]:
        if ch == current:
            count += 1
        else:
            out.append(str(count) + current)
            current = ch
            count = 1
    out.append(str(count) + current)
    return "".join(out)

