def coin_change_min(coins: list[int], amount: int) -> int:
    inf = amount + 1
    best = [inf] * (amount + 1)
    best[0] = 0
    for value in range(1, amount + 1):
        for coin in coins:
            if coin <= value and best[value - coin] + 1 < best[value]:
                best[value] = best[value - coin] + 1
    return -1 if best[amount] == inf else best[amount]

