def modular_inverse(a: int, m: int) -> int:
    if m < 2:
        return -1
    g, x, _ = _egcd(a % m, m)
    if g != 1:
        return -1
    return x % m


def _egcd(a: int, b: int):
    if a == 0:
        return (b, 0, 1)
    g, x, y = _egcd(b % a, a)
    return (g, y - (b // a) * x, x)

