def count_coprime_pairs(n: int) -> int:
    phi = list(range(n + 1))
    for p in range(2, n + 1):
        if phi[p] == p:
            for multiple in range(p, n + 1, p):
                phi[multiple] -= phi[multiple] // p
    total = 1
    for b in range(2, n + 1):
        total += phi[b]
    return total

