def avg_pool2d_valid(x: list[list[float]], k: int) -> list[list[float]]:
    if k < 1 or not x:
        return []
    rows = len(x)
    cols = len(x[0])
    if rows < k or cols < k:
        return []
    out = []
    for i in range(rows - k + 1):
        out_row = []
        for j in range(cols - k + 1):
            s = 0.0
            for di in range(k):
                for dj in range(k):
                    s += x[i + di][j + dj]
            out_row.append(s / (k * k))
        out.append(out_row)
    return out

