import math


def sigmoid_minmax(x: list[list[float]]) -> list[list[float]]:
    out = []
    for row in x:
        squashed = [_sigmoid(v) for v in row]
        lo = min(squashed)
        hi = max(squashed)
        span = hi - lo
        if span == 0.0:
            out.append([0.0 for _ in squashed])
        else:
            out.append([(v - lo) / span for v in squashed])
    return out


def _sigmoid(v: float) -> float:
    if v >= 0.0:
        return 1.0 / (1.0 + math.exp(-v))
    e = math.exp(v)
    return e / (1.0 + e)

